import os
import time
import logging
import requests

logger = logging.getLogger(__name__)
API_KEY = os.environ['ESTOQUE_API_KEY']

def buscar_saldos(url, max_tentativas=4):
    for tentativa in range(max_tentativas):
        try:
            resp = requests.get(url, headers={'Authorization': f'Bearer {API_KEY}'}, timeout=10)
            resp.raise_for_status()
            return resp.json()
        except requests.exceptions.RequestException:
            if tentativa == max_tentativas - 1:
                logger.exception('API de estoque falhou após %s tentativas', max_tentativas)
                raise
            time.sleep(2 ** tentativa)

def sincronizar(url, estoque):
    for sku, saldo_api in buscar_saldos(url).items():
        estoque[sku] = saldo_api # substitui o saldo: reexecutar não duplica
